# Compute AUROCs
geriatric_aurocs = {}
for name, s in preds_elder.items():
    auroc = roc_auc_score(y_val_elder, s)
    print(f"{name} AUROC (≥65): {auroc:.3f}")
    geriatric_aurocs[name] = auroc

# Prepare ROC data for Figure 2b
roc_data_geriatric = {}
for name, s in preds_elder.items():
    fpr, tpr, _ = roc_curve(y_val_elder, s)
    roc_data_geriatric[name] = {"fpr": fpr, "tpr": tpr, "auroc": geriatric_aurocs[name]}

plot_roc_geriatric(roc_data_geriatric, save_path=str(fig_dir / "figure2b_roc_geriatric.tiff"))
print("Figure 2b saved.")
